helpers.makeContext:
function makeContext(open: boolean): { context: Parameters<typeof runCommand>[1]; modalGestureWrites: unknown[] } {
  const modalGestureWrites: unknown[] = [];
  const callable = (): unknown => undefined;
  const state: Record<string, unknown> = new Proxy({}, {
    get: (): unknown => callable,
  });
  const ui: Record<string, unknown> = new Proxy({}, {
    get: (_target: Record<string, unknown>, property: string): unknown => {
      if (property === 'setModalGesture') {
        return (gesture: unknown): void => { modalGestureWrites.push(gesture); };
      }
      if (property === 'selection') {
        return (): unknown[] => [];
      }
      if (property === 'viewport') {
        return (): { zoom: number } => ({ zoom: 1 });
      }
      if (property === 'overlay') {
        return (): undefined => undefined;
      }
      return callable;
    },
  });
  const context: Parameters<typeof runCommand>[1] = {
    state: state as Parameters<typeof runCommand>[1]['state'],
    ui: ui as Parameters<typeof runCommand>[1]['ui'],
    geometry: undefined,
    rect: { left: 0, top: 0, width: 1, height: 1 } as Parameters<typeof runCommand>[1]['rect'],
    save: (): void => undefined,
    focusInspector: (): void => undefined,
    beginTextEdit: (): void => undefined,
  };
  if (open) {
    modalGestureWrites.push({ open: true });
  }
  return { context, modalGestureWrites: modalGestureWrites.slice(open ? 1 : 0) };
}

