helpers.makeGeometry:
const makeGeometry = (refs: Array<any>): any => {
  const byKey: { [key: string]: any } = {};
  for (const ref of refs) {
    byKey[`${ref.kind}:${ref.id}`] = {
      bounds: { minX: 0, minY: 0, maxX: 10, maxY: 10 },
      parentGroup: undefined,
    };
  }
  return { byKey, diagram: {} };
};

helpers.makeRecordingContext:
const makeRecordingContext = (geometry: unknown): any => {
  const calls: Array<Array<unknown>> = [];
  return {
    geometry,
    calls,
    rect: { x: 0, y: 0, width: 0, height: 0 },
    ui: {},
    save: (): void => {},
    beginTextEdit: (_ref: unknown): void => {},
    state: {
      stylesheet: {},
      applyStyleEdit: (...args: Array<unknown>): void => { calls.push(args); },
    },
  };
};

